    function updateStudentWalls(data){wallWidgets.forEach(function(widget){var wall=cardWallState(data,widget.config.id),open=Boolean(room&&wall.open),cards=approvedCards(wall);widget.submit.disabled=!open;widget.category.disabled=!open;widget.text.disabled=!open;widget.state.textContent=open?"geöffnet":"geschlossen";widget.state.classList.toggle("is-open",open);if(!room)widget.status.textContent="Verbinde dich zuerst mit einem Klassenraum.";else if(!open&&document.activeElement!==widget.text)widget.status.textContent="Die Lehrkraft öffnet die Kartenwand an dieser Stelle.";else if(open&&!widget.status.textContent.includes("Eingereicht"))widget.status.textContent="Beiträge erscheinen nach Freigabe anonym an der Klassenwand.";widget.board.innerHTML=cardColumnsHtml(widget.config,cards,false);});}

    function setStatus(text,error){modalStatus.textContent=text||"";modalStatus.classList.toggle("error",!!error);if(pageStatus){pageStatus.textContent=text||"";pageStatus.classList.toggle("error",!!error);}}
    function open(){backdrop.hidden=false;modalInput.value=room;setTimeout(function(){(room?backdrop.querySelector(".live-close"):modalInput).focus();},0);if(room)refresh();}
    function close(){backdrop.hidden=true;launcher.focus();}
