  function dateText(seconds){if(!seconds)return "";try{return new Intl.DateTimeFormat("de-DE",{dateStyle:"medium",timeStyle:"short"}).format(new Date(Number(seconds)*1000));}catch(e){return new Date(Number(seconds)*1000).toLocaleString("de-DE");}}
  function dateInputValue(date){var d=date instanceof Date?date:new Date(date);if(Number.isNaN(d.getTime()))return"";return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");}
