  function downloadCsv(data){var rows=[["Raumbezeichnung","Stundencode","Beginn","Ende","Aktivität","Frage","Antwort","Richtig","Stimmen","Anteil","Anzeige","Status"]];exportPolls(data).forEach(function(poll){pollQuestions(poll).forEach(function(question){var n=total(question.counts);(question.options||[]).forEach(function(option,i){var count=Number((question.counts||[])[i]||0),percent=n?Math.round(count*1000/n)/10:0;rows.push([data.label||"",data.room||room,dateText(poll.startedAt),dateText(poll.closedAt),poll.question,question.question,option,question.correctIndex!=null&&Number(question.correctIndex)===i?"ja":"",count,String(percent).replace(".",",")+" %",poll.reveal?"freigegeben":"verborgen",poll.closed?"geschlossen":"laufend"]);});});});download("\ufeff"+rows.map(function(row){return row.map(csvCell).join(";");}).join("\r\n"),"text/csv;charset=utf-8",fileBase(data)+".csv");}
  function downloadHtml(data){var number=0,sections=exportPolls(data).map(function(poll){return pollQuestions(poll).map(function(question){number++;var n=total(question.counts),rows=(question.options||[]).map(function(option,i){var count=Number((question.counts||[])[i]||0),percent=n?Math.round(count*100/n):0,correct=question.correctIndex!=null&&Number(question.correctIndex)===i;return "<tr"+(correct?' class="correct"':'')+"><th>"+letters(i)+" · "+esc(option)+"</th><td>"+count+"</td><td>"+percent+" %</td></tr>";}).join("");return "<section><h2>"+number+". "+esc(question.question)+"</h2><p>"+n+" Antworten · "+(poll.closed?"geschlossen":"laufend")+"</p><table><tbody>"+rows+"</tbody></table></section>";}).join("");}).join("");var html='<!doctype html><html lang="de"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'"><title>Abstimmungsergebnisse</title><style>body{font:16px/1.5 system-ui,sans-serif;color:#20252b;max-width:900px;margin:40px auto;padding:0 24px}h1,h2{font-family:Georgia,serif}table{border-collapse:collapse;width:100%}th,td{border:1px solid #bbc2ca;padding:.55rem;text-align:left}.correct{background:#e3f2ed}</style></head><body><h1>Abstimmungsergebnisse</h1><p><b>'+esc(roomTitle(data))+'</b></p>'+sections+'<p>Anonyme Summen ohne Namen oder Einzelantworten.</p></body></html>';download(html,"text/html;charset=utf-8",fileBase(data)+".html");}

