    window.RELIGION_CLASSROOM.startTeaching=function(payload){return request('start_teaching',payload).then(function(data){teachingContext=Object.assign({room:data.room},data.teaching);render(data);loadPreparedRooms();if(teachingContext.mode==='temporary')scheduleManagerJoin(true);return data;});};
