      pauseResume:function(){if(!room)return Promise.reject(new Error("Zuerst eine Stunde bereitstellen."));var running=current&&current.timer&&current.timer.running;return request(running?"pause_timer":"resume_timer",{room:room}).then(function(data){render(data);return data;});},
